func:
// 로컬(팜로컬)에서 규칙을 만들거나 고치면 SQLite 에만 들어가고
// 엔진이 쓰는 global.automationRules 에는 반영되지 않았다.
// 인터넷이 끊긴 동안 만든 규칙이 복구될 때까지 동작하지 않는다는 뜻이라,
// 팜로컬 모드의 존재 이유와 어긋난다. 쓰기 직후 다시 읽어 캐시를 맞춘다.
// enabled 로 거르지 않는다 — 토글로 끈 규칙도 읽어야 캐시에서 내릴 수 있다.
var farmId = env.get('FARM_ID') || global.get('farmId') || 'farm_0001';
msg.topic = 'SELECT * FROM automation_rules WHERE farm_id = $1';
msg.payload = [farmId];
return msg;

// SQLite 행을 기존 캐시 위에 id 로 덮어쓴다(병합). SQLite 로 통째로 갈아끼우지 않는다 —
// A(클라우드→SQLite 미러)가 한 번도 돌지 않은 상태(부팅 직후 오프라인 등)에서는 SQLite 에
// 방금 만든 로컬 규칙 하나뿐이라, 그대로 덮으면 엔진이 들고 있던 클라우드 규칙이 전부 사라진다.
var rows = msg.payload || [];
var cache = {};
(global.get('automationRules') || []).forEach(function (r) { cache[r.id] = r; });
rows.forEach(function (r) {
    cache[r.id] = {
        id: r.id, farm_id: r.farm_id, house_id: r.house_id, name: r.name,
        enabled: r.enabled ? 1 : 0,
        condition_logic: r.condition_logic || 'AND', group_logic: r.group_logic || 'AND',
        conditions: r.conditions, actions: r.actions,
        cooldown_seconds: r.cooldown_seconds || 60, priority: r.priority || 10,
        last_triggered_at: r.last_triggered_at, trigger_count: r.trigger_count || 0
    };
});
// 엔진은 켜진 규칙만 든다. 로컬에서 토글로 끈 규칙은 여기서 빠진다.
var rules = Object.keys(cache).map(function (k) { return cache[k]; })
    .filter(function (r) { return r.enabled === 1; });

global.set('automationRules', rules);
global.set('automationRulesUpdatedAt', new Date().toISOString());
node.warn('📋 로컬 규칙 변경 반영: ' + rules.length + '개');
node.status({ fill: 'blue', shape: 'dot', text: rules.length + '개 (로컬 ' + new Date().toLocaleTimeString() + ')' });

// ④ 시간 스케줄러가 시간 전용 규칙을 다시 계획하도록 넘긴다.
// 빠뜨리면 센서 규칙(② 60초 폴링)은 살아나지만 시간 규칙은 다음 클라우드 동기화까지 예약되지 않는다.
msg.automationRules = rules;
return msg;
